mapper.select:
SELECT id, pet_id, vaccine_name, vaccinated_on, next_due_on, batch_no, vet_name, created_at FROM pet_vaccinations
WHERE pet_id = #{petId}
ORDER BY vaccinated_on ASC, id ASC

mapper.insert:
INSERT INTO pet_vaccinations (
    pet_id, vaccine_name, vaccinated_on, next_due_on, batch_no, vet_name
) VALUES (
    #{petId}, #{vaccineName}, #{vaccinatedOn}, #{nextDueOn}, #{batchNo}, #{vetName}
)
